// TestRegistryValidateFactories tests corresponding registry method.
func TestRegistryValidateFactories(t *testing.T) {
	tests := []struct {
		name    string
		options []Option
		wantErr func(t *testing.T, err error)
	}{
		{
			name: "NoValidationErrors",
			options: []Option{
				NewFactory(func(bool) (int, error) { return 1, nil }),
				NewFactory(func(string) (bool, error) { return true, nil }),
				NewFactory(func() (string, error) { return "s", nil }),
				NewEntrypoint(func(int, bool, string) {}),
			},
			wantErr: func(t *testing.T, err error) {
				equal(t, err, nil)
			},
		},
		{
			name: "ServiceNotResolvedError",
			options: []Option{
				NewFactory(func(bool) (int, error) { return 0, nil }),
				NewFactory(func(string) (int32, error) { return 0, nil }),
				NewEntrypoint(func(int, int32) {}),
			},
			wantErr: func(t *testing.T, err error) {
				equal(t, errors.Is(err, ErrDependencyNotResolved), true)

				unwrap, ok := err.(interface{ Unwrap() []error })
				equal(t, ok, true)
				errs := unwrap.Unwrap()
				equal(t, len(errs), 2)

				equal(t, errors.Is(errs[0], ErrDependencyNotResolved), true)
				equal(t, normalizeSourceLines(errs[0].Error()), ""+
					"dependency not resolved: bool\n\n"+
					"Traceback:\n"+
					"  Factory for int")

				equal(t, errors.Is(errs[1], ErrDependencyNotResolved), true)
				equal(t, normalizeSourceLines(errs[1].Error()), ""+
					"dependency not resolved: string\n\n"+
					"Traceback:\n"+
					"  Factory for int32")
			},
		},
		{
			name: "ServiceDuplicatedError",
			options: []Option{
				NewFactory(func() (string, error) { return "s1", nil }),
				NewFactory(func() (string, error) { return "s2", nil }),
				NewEntrypoint(func(string) {}),
			},
			wantErr: func(t *testing.T, err error) {
				equal(t, errors.Is(err, ErrFactoryTypeDuplicated), true)

				unwrap, ok := err.(interface{ Unwrap() []error })
				equal(t, ok, true)
				errs := unwrap.Unwrap()
				equal(t, len(errs), 2)

				equal(t, errors.Is(errs[0], ErrFactoryTypeDuplicated), true)
				equal(t, normalizeSourceLines(errs[0].Error()), ""+
					"factory type duplicated: string\n\n"+
					"Traceback:\n"+
					"  Factory for string")

				equal(t, errors.Is(errs[1], ErrFactoryTypeDuplicated), true)
				equal(t, normalizeSourceLines(errs[1].Error()), ""+
					"factory type duplicated: string\n\n"+
					"Traceback:\n"+
					"  Factory for string")
			},
		},
		{
			name: "CircularDependencyErrors",
			options: []Option{
				NewFactory(func(bool) (int, error) { return 1, nil }),
				NewFactory(func(string) (bool, error) { return true, nil }),
				NewFactory(func(int) (string, error) { return "s", nil }),
				NewEntrypoint(func(int, bool, string) {}),
			},
			wantErr: func(t *testing.T, err error) {
				equal(t, errors.Is(err, ErrCircularDependency), true)

				unwrap, ok := err.(interface{ Unwrap() []error })
				equal(t, ok, true)
				errs := unwrap.Unwrap()
				equal(t, len(errs), 3)

				equal(t, errors.Is(errs[0], ErrCircularDependency), true)
				equal(t, normalizeSourceLines(errs[0].Error()), ""+
					"circular dependency\n\n"+
					"Traceback:\n"+
					"  Factory for int")

				equal(t, errors.Is(errs[1], ErrCircularDependency), true)
				equal(t, normalizeSourceLines(errs[1].Error()), ""+
					"circular dependency\n\n"+
					"Traceback:\n"+
					"  Factory for bool")

				equal(t, errors.Is(errs[2], ErrCircularDependency), true)
				equal(t, normalizeSourceLines(errs[2].Error()), ""+
					"circular dependency\n\n"+
					"Traceback:\n"+
					"  Factory for string")
			},
		},
		{
			name: "ComplexErrors",
			options: []Option{
				NewFactory(func(struct{ X int }) string { return "s1" }),  // not resolved, duplicate
				NewFactory(func(bool) (int, error) { return 1, nil }),     // cycle
				NewFactory(func(int) (bool, error) { return true, nil }),  // cycle
				NewFactory(func() string { return "s2" }),                 // duplicate
				NewEntrypoint(func(struct{ X int }) error { return nil }), // not resolved
			},
			wantErr: func(t *testing.T, err error) {
				equal(t, errors.Is(err, ErrDependencyNotResolved), true)
				equal(t, errors.Is(err, ErrFactoryTypeDuplicated), true)
				equal(t, errors.Is(err, ErrCircularDependency), true)

				unwrap, ok := err.(interface{ Unwrap() []error })
				equal(t, ok, true)
				errs := unwrap.Unwrap()
				equal(t, len(errs), 6)

				equal(t, errors.Is(errs[0], ErrDependencyNotResolved), true)
				equal(t, normalizeSourceLines(errs[0].Error()), ""+
					"dependency not resolved: struct { X int }\n\n"+
					"Traceback:\n"+
					"  Factory for string")

				equal(t, errors.Is(errs[1], ErrDependencyNotResolved), true)
				equal(t, normalizeSourceLines(errs[1].Error()), ""+
					"dependency not resolved: struct { X int }\n\n"+
					"Traceback:\n"+
					"  Entrypoint")

				equal(t, errors.Is(errs[2], ErrFactoryTypeDuplicated), true)
				equal(t, normalizeSourceLines(errs[2].Error()), ""+
					"factory type duplicated: string\n\n"+
					"Traceback:\n"+
					"  Factory for string")

				equal(t, errors.Is(errs[3], ErrFactoryTypeDuplicated), true)
				equal(t, normalizeSourceLines(errs[3].Error()), ""+
					"factory type duplicated: string\n\n"+
					"Traceback:\n"+
					"  Factory for string")

				equal(t, errors.Is(errs[4], ErrCircularDependency), true)
				equal(t, normalizeSourceLines(errs[4].Error()), ""+
					"circular dependency\n\n"+
					"Traceback:\n"+
					"  Factory for int")

				equal(t, errors.Is(errs[5], ErrCircularDependency), true)
				equal(t, normalizeSourceLines(errs[5].Error()), ""+
					"circular dependency\n\n"+
					"Traceback:\n"+
					"  Factory for bool")
			},
		},
	}
	for _, tt := range tests {
		t.Run(tt.name, func(t *testing.T) {
			registry := &registry{}
			for _, option := range tt.options {
				equal(t, option.apply(registry), nil)
			}
			tt.wantErr(t, registry.validateRegistry())
		})
	}
}

// cycA, cycB and cycC model a dependency graph where an acyclic factory (cycA)
// can reach a cycle (cycB <-> cycC) that does not include it.
type (
	cycA int
	cycB int
	cycC int
)

// TestRegistryValidateCycle ensures cycle validation terminates properly.
func TestRegistryValidateCycle(t *testing.T) {
	registry := &registry{}
	options := []Option{
		// Acyclic root, registered first, depends on the cycle below.
		NewFactory(func(cycB) cycA { return 0 }),

		// cycB and cycC form a cycle that does not involve cycA.
		NewFactory(func(cycC) cycB { return 0 }),
		NewFactory(func(cycB) cycC { return 0 }),

		NewEntrypoint(func(cycA) {}),
	}
	for _, option := range options {
		equal(t, option.apply(registry), nil)
	}

	done := make(chan error, 1)
	go func() { done <- registry.validateRegistry() }()

	select {
	case err := <-done:
		equal(t, errors.Is(err, ErrCircularDependency), true)
	case <-time.After(5 * time.Second):
		t.Fatal("validateRegistry did not terminate: the cycle walk looped")
	}
}

// greeter and its implementations exercise regular interface resolution with more
// than one candidate.
type greeter interface{ greet() string }

// englishGreeter is the first registered greeter implementation.
type englishGreeter struct{}

// greet returns the English greeting.
func (englishGreeter) greet() string { return "hello" }

// frenchGreeter is the second registered greeter implementation.
type frenchGreeter struct{}

// greet returns the French greeting.
func (frenchGreeter) greet() string { return "bonjour" }

// TestRegistryResolveInterfaceSingle verifies that resolving an interface as a regular
// dependency returns the first registered implementation and does not spawn the others.
func TestRegistryResolveInterfaceSingle(t *testing.T) {
	var englishSpawned, frenchSpawned atomic.Int32
	var got string

	err := Run(
		NewFactory(func() englishGreeter { englishSpawned.Add(1); return englishGreeter{} }),
		NewFactory(func() frenchGreeter { frenchSpawned.Add(1); return frenchGreeter{} }),
		NewEntrypoint(func(g greeter) { got = g.greet() }),
	)

	equal(t, err, nil)
	equal(t, got, "hello")
	equal(t, englishSpawned.Load(), int32(1))
	equal(t, frenchSpawned.Load(), int32(0))
}

// TestRegistryResolveInterfaceMultiple verifies that resolving an interface through
// Multiple returns every registered implementation and spawns all of them.
func TestRegistryResolveInterfaceMultiple(t *testing.T) {
	var englishSpawned, frenchSpawned atomic.Int32
	var got []string

	err := Run(
		NewFactory(func() englishGreeter { englishSpawned.Add(1); return englishGreeter{} }),
		NewFactory(func() frenchGreeter { frenchSpawned.Add(1); return frenchGreeter{} }),
		NewEntrypoint(func(greeters Multiple[greeter]) {
			for _, g := range greeters {
				got = append(got, g.greet())
			}
		}),
	)

	equal(t, err, nil)
	equal(t, len(got), 2)
	equal(t, got[0], "hello")
	equal(t, got[1], "bonjour")
	equal(t, englishSpawned.Load(), int32(1))
	equal(t, frenchSpawned.Load(), int32(1))
}

