		"\nTraceback:"+
		"\n  Factory for *gontainer.testFmtLeaf"+
		"\n  Factory for *gontainer.testFmtMid"+
		"\n  Factory for *gontainer.testFmtRootA"+
		"\n  Entrypoint")
	equal(t, errors.Is(err, ErrFactoryReturnedError), true)
}

